package android.content;public class Context {public static final int BIND_AUTO_CREATE=1;public interface Router {boolean bind(Intent i,ServiceConnection c);void unbind(ServiceConnection c);}public static Router router;public boolean bindService(Intent i,ServiceConnection c,int f){return router.bind(i,c);}public void unbindService(ServiceConnection c){router.unbind(c);}public android.content.pm.PackageManager getPackageManager(){return new android.content.pm.PackageManager();}public String getPackageName(){return "com.videokit.app";}}
